def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the three adjacent nonzero cells forming the pattern on an edge.
    for r in range(h):
        for c in range(w - 2):
            vals = grid[r][c:c+3]
            if all(vals) and len(set(vals)) == 3 and (r == 0 or r == h-1):
                colors = vals
                inward = 1 if r == 0 else -1

                # The center color extends perpendicular to the edge.
                for rr in range(r, h if inward == 1 else -1, inward):
                    out[rr][c+1] = colors[1]

                # The two outer colors connect to matching markers on the side edges.
                for idx, color in ((0, colors[0]), (2, colors[2])):
                    seed_c = c + idx
                    for rr in range(h):
                        for cc in range(w):
                            if grid[rr][cc] == color and (rr, cc) != (r, seed_c):
                                if cc in (0, w-1):
                                    step = 1 if inward == 1 else -1
                                    for y in range(r, rr + step, step):
                                        out[y][seed_c] = color
                                    lo, hi = sorted((seed_c, cc))
                                    for x in range(lo, hi + 1):
                                        out[rr][x] = color
                return out
    return out
